final String readUtf(final int constantPoolEntryIndex,final char[] charBuffer){
    // Assume classFileBuffer is a ByteBuffer positioned at the start of the constant pool.
    // Seek to the entry offset (here we treat the index as an offset for simplicity).
    int offset = constantPoolEntryIndex;
    classFileBuffer.position(offset);
    // Read the tag byte; CONSTANT_Utf8 has tag value 1.
    byte tag = classFileBuffer.get();
    if (tag != 1) {
        throw new IllegalArgumentException("Expected CONSTANT_Utf8 tag but found: " + tag);
    }
    // Read the length of the UTF-8 string (unsigned short).
    int length = classFileBuffer.getShort() & 0xFFFF;
    // Read the UTF-8 bytes.
    byte[] bytes = new byte[length];
    classFileBuffer.get(bytes);
    // Decode the bytes into a String using UTF-8.
    String str = new String(bytes, java.nio.charset.StandardCharsets.UTF_8);
    // Copy the characters into the provided buffer (up to its capacity).
    int copyLen = Math.min(str.length(), charBuffer.length);
    str.getChars(0, copyLen, charBuffer, 0);
    return str;
}

