@Override public void generateGraph(Graph<V,E> target,Map<String,V> resultMap){
    // Add all vertices to the graph
    for (V v : resultMap.values()){
        target.addVertex(v);
    }
    // Split vertices into two partitions for a complete bipartite graph
    List<V> allVertices = new ArrayList<>(resultMap.values());
    int mid = allVertices.size() / 2;
    List<V> left = allVertices.subList(0, mid);
    List<V> right = allVertices.subList(mid, allVertices.size());
    // Add edges between every vertex in left and every vertex in right
    for (V u : left){
        for (V v : right){
            target.addEdge(u, v);
        }
    }
}

