protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph){
    List<E> edgeList = new ArrayList<>();
    List<V> vertexList = new ArrayList<>();
    if (tour.isEmpty()){
        return new SimpleGraphPath<>(graph, vertexList, edgeList, 0.0);
    }
    // Build degree map to find a start vertex (degree 1 for undirected or directed)
    Map<V,Integer> degree = new HashMap<>();
    for (E e : tour){
        V src = graph.getEdgeSource(e);
        V tgt = graph.getEdgeTarget(e);
        degree.put(src, degree.getOrDefault(src,0)+1);
        degree.put(tgt, degree.getOrDefault(tgt,0)+1);
    }
    V start = null;
    for (Map.Entry<V,Integer> entry : degree.entrySet()){
        if (entry.getValue() == 1){
            start = entry.getKey();
            break;
        }
    }
    if (start == null){
        // fallback: pick source of first edge
        start = graph.getEdgeSource(tour.iterator().next());
    }
    vertexList.add(start);
    Set<E> remaining = new HashSet<>(tour);
    V current = start;
    while (!remaining.isEmpty()){
        E nextEdge = null;
        for (E e : remaining){
            V src = graph.getEdgeSource(e);
            V tgt = graph.getEdgeTarget(e);
            if (src.equals(current) || tgt.equals(current)){
                nextEdge = e;
                break;
            }
        }
        if (nextEdge == null){
            break; // disconnected or cycle
        }
        edgeList.add(nextEdge);
        V nextVertex = graph.getEdgeSource(nextEdge).equals(current) ?
                       graph.getEdgeTarget(nextEdge) :
                       graph.getEdgeSource(nextEdge);
        vertexList.add(nextVertex);
        current = nextVertex;
        remaining.remove(nextEdge);
    }
    double weight = 0.0;
    for (E e : edgeList){
        weight += graph.getEdgeWeight(e);
    }
    return new SimpleGraphPath<>(graph, vertexList, edgeList, weight);
}

