public void abbreviate(final int nameStart, final StringBuffer buf) {
    if (buf == null || nameStart < 0 || nameStart >= buf.length()) {
        return;
    }
    // Extract the name starting at the given index
    String name = buf.substring(nameStart);
    // Split the name on common delimiters (dot, underscore, space)
    String[] parts = name.split("[._\\s]+");
    // Build the abbreviation by taking the first character of each part
    StringBuilder abbr = new StringBuilder();
    for (String part : parts) {
        if (!part.isEmpty()) {
            abbr.append(part.charAt(0));
        }
    }
    // Append the abbreviation to the buffer
    buf.append(abbr);
}

